import React, { useState, useEffect } from 'react';
import Icon from '../../components/UI/Icon';
import { KPICard } from '../../components/UI/KPICard';
import { StatusBadge } from '../../components/UI/StatusBadge';
import { api } from '../../services/api';
import { useToast } from '../../context/ToastContext';
import { 
  ResponsiveContainer, 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  Tooltip, 
  CartesianGrid
} from 'recharts';

export function Dashboard({ setActiveTab }) {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [range, setRange] = useState('THIS_MONTH');
  const { error } = useToast();

  const fetchDashboardData = async () => {
    setLoading(true);
    try {
      const res = await api.dashboard.get(range);
      if (res?.data) {
        setStats(res.data);
      }
    } catch (err) {
      error('Failed to load dashboard metrics: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDashboardData();
  }, [range]);

  if (loading && !stats) {
    return (
      <div className="flex items-center justify-center min-h-[500px]">
        <div className="text-center">
          <div className="flex justify-center mb-3">
            <Icon name="loader" size="2xl" spin={true} className="text-slate-900" ariaHidden={true} />
          </div>
          <p className="text-sm font-semibold text-slate-500">Loading Bharat Impex Enterprise Metrics...</p>
        </div>
      </div>
    );
  }

  const stockSummary = stats?.stock_summary || {};
  const todayKpis = stats?.today_kpis || {};
  const activeOrders = stats?.active_orders || [];
  const lowStockAlerts = stats?.low_stock_alerts || [];
  const funnel = stats?.production_funnel || [];
  const monthlyTrends = stats?.monthly_trends || [];
  const rejectionPareto = stats?.rejection_pareto || [];

  return (
    <div className="space-y-6">
      {/* Top Header Filter Bar */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 bg-white border border-slate-200/90 p-5 rounded-2xl shadow-xs">
        <div>
          <h1 className="text-xl font-black text-slate-900 tracking-tight">Bharat Impex Factory Dashboard</h1>
          <p className="text-xs text-slate-500 font-medium">Real-time material flow, WIP stages, and stock ledger synchronization</p>
        </div>

        <div className="flex items-center gap-2 self-stretch sm:self-auto flex-wrap">
          <button
            type="button"
            onClick={() => setActiveTab('sku_tracker')}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-blue-600 text-white hover:bg-blue-700 text-xs font-bold transition-colors shadow-xs cursor-pointer"
          >
            <Icon name="filespreadsheet" size="xs" className="text-white" ariaHidden={true} />
            <span>Open SKU Tracking Sheet</span>
          </button>

          <div className="flex bg-slate-100 border border-slate-200 rounded-xl p-1 text-xs">
            {['TODAY', 'THIS_WEEK', 'THIS_MONTH', 'LAST_MONTH'].map((r) => (
              <button
                key={r}
                type="button"
                onClick={() => setRange(r)}
                className={`px-3 py-1 rounded-lg font-bold transition-colors cursor-pointer ${
                  range === r ? 'bg-white text-blue-700 shadow-xs' : 'text-slate-600 hover:text-slate-900'
                }`}
              >
                {r.replace('_', ' ')}
              </button>
            ))}
          </div>

          <button
            type="button"
            onClick={fetchDashboardData}
            title="Refresh Data"
            aria-label="Refresh Data"
            className="p-2 rounded-xl bg-white hover:bg-slate-50 text-slate-600 transition-colors border border-slate-200 shadow-xs cursor-pointer"
          >
            <Icon name="refresh" size="xs" spin={loading} className={loading ? 'text-blue-600' : ''} ariaHidden={true} />
          </button>
        </div>
      </div>

      {/* Primary KPI Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <KPICard
          title="Raw Material Stock"
          value={`${Number(stockSummary.total_rm_qty || 0).toLocaleString()} KG`}
          subtitle="Available brass & components"
          icon="boxes"
          color="blue"
          onClick={() => setActiveTab('inventory')}
        />

        <KPICard
          title="Finished Goods Stock"
          value={`${Number(stockSummary.total_fg_qty || 0).toLocaleString()} PCS`}
          subtitle="Ready for dispatch & sales"
          icon="packagecheck"
          color="emerald"
          onClick={() => setActiveTab('inventory')}
        />

        <KPICard
          title="Today's Production"
          value={`${Number(todayKpis.today_production_qty || 0).toLocaleString()} PCS`}
          subtitle={`Rejections: ${Number(todayKpis.today_rejection_qty || 0).toLocaleString()}`}
          icon="factory"
          color="purple"
          onClick={() => setActiveTab('production')}
        />

        <KPICard
          title="Today's Purchases"
          value={`₹${Number(todayKpis.today_purchase_val || 0).toLocaleString()}`}
          subtitle={`${Number(todayKpis.today_purchase_qty || 0).toLocaleString()} units input`}
          icon="shopping-cart"
          color="amber"
          onClick={() => setActiveTab('purchase')}
        />
      </div>

      {/* Production Funnel (WIP by Dynamic Stages) */}
      <div className="bg-white p-6 rounded-2xl border border-slate-200/90 shadow-xs">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-2">
            <Icon name="flame" size="md" className="text-amber-500" ariaHidden={true} />
            <h3 className="text-base font-black text-slate-900 tracking-tight">Multi-Stage Manufacturing Funnel (WIP)</h3>
          </div>
          <button
            type="button"
            onClick={() => setActiveTab('sku_tracker')}
            className="text-xs font-bold text-slate-800 hover:text-slate-900 flex items-center gap-1 underline cursor-pointer"
          >
            <span>Live SKU Pipeline Sheet</span>
            <Icon name="next" size="xs" ariaHidden={true} />
          </button>
        </div>

        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 lg:grid-cols-9 gap-2.5">
          {funnel.map((stage, idx) => {
            const stageIcon = stage.icon_key || stage.process_code?.toLowerCase() || 'factory';
            return (
              <div
                key={stage.process_code || idx}
                className="bg-white border border-slate-200/90 p-3.5 rounded-xl flex flex-col justify-between hover:border-slate-400 hover:shadow-xs transition-all"
              >
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-[10px] font-black text-slate-500 uppercase tracking-wider block">
                      Stage {idx + 1}
                    </span>
                    <Icon name={stageIcon} size="xs" className="text-slate-400" ariaHidden={true} />
                  </div>
                  <p className="text-xs font-bold text-slate-900 truncate mt-0.5" title={stage.process_name}>
                    {stage.process_name}
                  </p>
                </div>

                <div className="mt-3 pt-2 border-t border-slate-100 space-y-1 text-[11px]">
                  <div className="flex justify-between text-slate-500 font-medium">
                    <span>WIP:</span>
                    <span className="font-bold text-slate-900">{Number(stage.in_progress_qty || 0)}</span>
                  </div>
                  <div className="flex justify-between text-slate-500 font-medium">
                    <span>Done:</span>
                    <span className="font-bold text-emerald-700">{Number(stage.completed_qty || 0)}</span>
                  </div>
                  {Number(stage.total_rejected || 0) > 0 && (
                    <div className="flex justify-between text-rose-600 font-bold">
                      <span>Rej:</span>
                      <span>{Number(stage.total_rejected || 0)}</span>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Analytics Charts Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Trend 1: Purchase vs Sales (₹) */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200/90 shadow-xs flex flex-col">
          <h3 className="text-sm font-black text-slate-900 tracking-tight mb-1">Financial Movement Trends (Last 6 Months)</h3>
          <p className="text-xs text-slate-500 font-medium mb-4">Total purchase input cost vs sales billing valuation</p>

          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={monthlyTrends}>
                <defs>
                  <linearGradient id="colorPur" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.15} />
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0} />
                  </linearGradient>
                  <linearGradient id="colorSale" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#10b981" stopOpacity={0.2} />
                    <stop offset="95%" stopColor="#10b981" stopOpacity={0} />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                <XAxis dataKey="month_label" stroke="#64748b" fontSize={11} />
                <YAxis stroke="#64748b" fontSize={11} tickFormatter={(v) => `₹${v / 1000}k`} />
                <Tooltip
                  contentStyle={{ backgroundColor: '#ffffff', borderColor: '#e2e8f0', borderRadius: '12px', fontSize: '12px', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)' }}
                />
                <Area type="monotone" dataKey="purchase_amount" name="Purchase (₹)" stroke="#2563eb" strokeWidth={2} fillOpacity={1} fill="url(#colorPur)" />
                <Area type="monotone" dataKey="sale_amount" name="Sales (₹)" stroke="#10b981" strokeWidth={2} fillOpacity={1} fill="url(#colorSale)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Trend 2: Production vs Rejection Pareto */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200/90 shadow-xs flex flex-col">
          <h3 className="text-sm font-black text-slate-900 tracking-tight mb-1">Top Rejection Defect Reasons (Pareto)</h3>
          <p className="text-xs text-slate-500 font-medium mb-4">Shopfloor quality defects requiring process mitigation</p>

          <div className="h-64 w-full flex flex-col justify-center">
            {rejectionPareto.length === 0 ? (
              <div className="text-center py-10 text-slate-400 text-xs">
                <Icon name="circlecheck" size="2xl" className="mx-auto text-emerald-500 mb-2 opacity-80" ariaHidden={true} />
                <p>0 Defect Incidents Recorded in this Period</p>
              </div>
            ) : (
              <div className="space-y-3">
                {rejectionPareto.map((rej, idx) => {
                  const maxQty = Math.max(...rejectionPareto.map((r) => Number(r.total_qty)));
                  const pct = Math.round((Number(rej.total_qty) / (maxQty || 1)) * 100);

                  return (
                    <div key={rej.reason_name || idx} className="space-y-1">
                      <div className="flex justify-between text-xs font-semibold">
                        <span className="text-slate-700 flex items-center gap-1.5">
                          <span className="w-2 h-2 rounded-full bg-rose-500" />
                          {rej.reason_name} ({rej.category})
                        </span>
                        <span className="font-bold text-rose-600 font-mono">
                          {Number(rej.total_qty)} units ({rej.incident_count} events)
                        </span>
                      </div>
                      <div className="w-full bg-slate-100 rounded-full h-2 overflow-hidden">
                        <div
                          className="bg-gradient-to-r from-rose-500 to-amber-500 h-full rounded-full transition-all duration-500"
                          style={{ width: `${pct}%` }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Lower Grids: Active Production Orders & Low Stock Alerts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Active Production Queue */}
        <div className="bg-white rounded-2xl border border-slate-200/90 shadow-xs overflow-hidden">
          <div className="p-4 border-b border-slate-200 flex items-center justify-between bg-slate-50/70">
            <h3 className="text-sm font-black text-slate-900 flex items-center gap-2">
              <Icon name="factory" size="xs" className="text-slate-700" ariaHidden={true} />
              <span>Active Production Queue</span>
            </h3>
            <button
              type="button"
              onClick={() => setActiveTab('production')}
              className="text-xs text-slate-800 hover:text-slate-900 font-bold underline flex items-center gap-1 cursor-pointer"
            >
              <span>Manage Orders</span>
              <Icon name="next" size="xs" ariaHidden={true} />
            </button>
          </div>

          <div className="divide-y divide-slate-100">
            {activeOrders.length === 0 ? (
              <div className="text-center py-10 text-slate-400 text-xs">No active production orders</div>
            ) : (
              activeOrders.map((ord) => (
                <div key={ord.id} className="p-4 hover:bg-slate-50/80 transition-colors flex items-center justify-between">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-mono font-bold text-slate-900">{ord.production_number}</span>
                      <StatusBadge status={ord.priority} size="xs" />
                      <StatusBadge status={ord.status} size="xs" />
                    </div>
                    <p className="text-xs font-bold text-slate-900 mt-1">{ord.product_name}</p>
                    <p className="text-[11px] text-slate-500 mt-0.5">
                      Target: <span className="text-slate-800 font-semibold">{Number(ord.planned_quantity)} {ord.unit_code}</span> • Current Stage: <span className="text-slate-900 font-semibold">{ord.current_stage_name || 'Pending Start'}</span>
                    </p>
                  </div>

                  <div className="text-right text-xs">
                    <span className="text-slate-400 text-[11px]">Progress</span>
                    <p className="font-bold text-emerald-700 font-mono">
                      {ord.completed_stages} / {ord.total_stages} Stages
                    </p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {/* Low Stock Watchlist */}
        <div className="bg-white rounded-2xl border border-slate-200/90 shadow-xs overflow-hidden">
          <div className="p-4 border-b border-slate-200 flex items-center justify-between bg-slate-50/70">
            <h3 className="text-sm font-black text-slate-900 flex items-center gap-2">
              <Icon name="warning" size="xs" className="text-amber-500" ariaHidden={true} />
              <span>Raw Material Reorder Alerts</span>
            </h3>
            <button
              type="button"
              onClick={() => setActiveTab('purchase')}
              className="text-xs text-amber-700 hover:text-amber-800 font-bold underline flex items-center gap-1 cursor-pointer"
            >
              <span>Order Materials</span>
              <Icon name="next" size="xs" ariaHidden={true} />
            </button>
          </div>

          <div className="divide-y divide-slate-100">
            {lowStockAlerts.length === 0 ? (
              <div className="text-center py-10 text-emerald-700 text-xs flex flex-col items-center gap-1 font-semibold">
                <Icon name="circlecheck" size="xl" className="text-emerald-600" ariaHidden={true} />
                <span>All raw materials are above reorder thresholds</span>
              </div>
            ) : (
              lowStockAlerts.map((item) => (
                <div key={item.id} className="p-4 hover:bg-slate-50/80 transition-colors flex items-center justify-between">
                  <div>
                    <span className="text-xs font-mono font-bold text-amber-700">{item.material_code}</span>
                    <p className="text-xs font-bold text-slate-900 mt-0.5">{item.material_name}</p>
                    <p className="text-[11px] text-slate-500">
                      Reorder Threshold: {Number(item.reorder_level)} {item.unit_code}
                    </p>
                  </div>

                  <div className="text-right">
                    <span className="text-xs font-bold text-rose-600 font-mono block">
                      {Number(item.available_quantity)} {item.unit_code}
                    </span>
                    <span className="text-[10px] text-rose-700 font-bold uppercase bg-rose-50 px-2 py-0.5 rounded-full border border-rose-200">
                      Low Stock
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
